head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/bns_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
scwin.vScrenID = "ULDBNS90004.xml";
scwin.vMktactTpCd = '';
scwin.fn_GetPar, scwin.fn_SetPar;
scwin.vTempRsn = '';
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};

/********************************************** 
 * 함수명   : fn_Return
 * 설명       : 신청 및 접수 데이터를 반송처리한다.
 ***********************************************/
scwin.fn_Return = function() {
    var url = "/bns/BnsCommon.do?method=processApplAcptRet";
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_03;
    var param = "BND_APPL_ID=" + $c.stf.getObjectValue(txb_BndApplId);
    param += ", BND_LIST_PROCS_TP_CD=" + $c.stf.getObjectValue(txb_BndListProcsTpCd);
    param += ", RET_RSN=" + $c.stf.getObjectValue(txa_RetRsn);
    trs_Save.Action = $c.lc.fn_encodeNSession(url);
    trs_Save.KeyName = "toinb_dataid4";
    trs_Save.KeyValue = "JSP(I:pInput=dts_Return)";
    trs_Save.Parameters = param;
    trs_Save.Post();
};


/********************************************** 
 * 함수명   : fn_SetParam
 * 설명       : 부모창에서 받은 데이터를 설정한다.
 ***********************************************/
scwin.fn_SetParam = function() {
    var prt = $c.frame.path("../");
    if (prt != undefined) {
        scwin.fn_GetPar = prt.scwin.fn_GetPar;
        scwin.fn_SetPar = prt.scwin.fn_SetPar;
    }
    if (scwin.fn_GetPar != undefined) {
        var arrPar = new Array();
        scwin.fn_GetPar(arrPar);
        $c.stf.setObjectValue(txb_BndApplId, arrPar[0].BND_APPL_ID);
        $c.stf.setObjectValue(txb_BndListProcsTpCd, arrPar[0].BND_LIST_PROCS_TP_CD);
        $c.stf.setObjectValue(txb_IsurNm, arrPar[0].ISUR_NM);
        $c.stf.setObjectValue(txb_IsuNm, arrPar[0].ISU_NM);
        if (arrPar[0].MKTACT_TP_CD != undefined) {
            scwin.vMktactTpCd = arrPar[0].MKTACT_TP_CD;
        }
    }
};




/********************************************** 
 * 함수명   : fn_HideIsuNm
 * 설명       : 상호변경에서 호출 시, 한글기준명 숨기기
 ***********************************************/
scwin.fn_HideIsuNm = function() {
    if (scwin.vMktactTpCd == '201') {
        $c.stf.showObj(lbl_IsuNm, false);
        $c.stf.showObj(txb_IsuNm, false);
        lbl_RetCd.style.top = '61px';
        rdo_RetCd.style.top = '61px';
        lbl_RetRsn.style.top = '87px';
        txa_RetRsn.style.top = '87px';
    }
};
scwin.gform_onload = function() {
    //숨기기
    $c.stf.showObj(txb_BndListProcsTpCd, false);
    //호출파라미터설정
    scwin.fn_SetParam();
    //상호변경에서 호출 시, 한글기준명 숨기기
    scwin.fn_HideIsuNm();

    //데이터셋정의

    //dts_Return.setDataHeader(); // W-Craft 주석처리 및 필요시 asis 파라미터 확인 
    dts_Return.insertRow();
};
scwin.btn_Close_onclick = async function() {
    await $c.frame.CloseFrame();
};
scwin.btn_Return_onclick = function() {
    if ($c.stf.getObjectValue(txb_BndApplId) == "") return;
    if ($c.stf.getObjectValue(txa_RetRsn).length == 0) {
        $c.win.alert("반송 사유를 입력하십시오");
        txa_RetRsn.focus();
        return;
    }
    if ($c.stf.getObjectValue(txa_RetRsn).length > 20) {
        $c.win.alert("반송 사유를 20자 이내로 입력하십시오.");
        txa_RetRsn.focus();
        return;
    }
    if (!window.confirm("반송처리 하시겠습니까?")) return;
    scwin.fn_Return();
};
scwin.trs_Save_OnFail = function() {
    $c.win.alert($c.stf.getMessageParam("MSG-0002"));
};
scwin.trs_Save_OnSuccess = async function() {
    $c.win.alert('[반송]처리 성공하였습니다.');
    var arrPar = new Array();
    arrPar[0] = {
        SUCCESS_YN: 'Y'
    };

    //var parentFrame = frame.Provider("../");
    scwin.fn_SetPar(arrPar);
    await $c.frame.CloseFrame();
};
scwin.rdo_RetCd_OnClick = function() {
    var retRsn = $c.stf.getObjectValue(txa_RetRsn);
    var rdoCd = $c.stf.getObjectValue(rdo_RetCd);
    $c.stf.setObjectValue(txa_RetRsn, '');
    var rdoText = '';
    if (rdoCd == '1') {
        rdoText = '중복신청';
    } else if (rdoCd == '2') {
        rdoText = '신청자요청';
    } else if (rdoCd == '3') {
        rdoText = '기재내용 오류';
    } else if (rdoCd == '4') {
        rdoText = '코드기부여';
    }
    $c.stf.setObjectValue(txa_RetRsn, rdoText);
    /*
    if(retRsn != '') {
    	setObjectValue(txa_RetRsn, rdoText+'\n'+ retRsn);
    }else {
    	setObjectValue(txa_RetRsn, rdoText);
    }
    */

};
scwin.txa_RetRsn_OnChange = function() {
    var rsn = $c.stf.getObjectValue(txa_RetRsn);
    if (rsn == '') return;
    if (rsn.length > 20) {
        $c.win.alert("반송 사유를 20자 이내로 입력하십시오.");
        $c.stf.setObjectValue(txa_RetRsn, '');
        $c.stf.setObjectValue(txa_RetRsn, scwin.vTempRsn);
    } else {
        scwin.vTempRsn = rsn;
    }
};
